INSERT INTO public.exercise_library (id, name, slug, body_area, movement_type, equipment, level, primary_muscles, secondary_muscles, instructions, image_paths, legacy_names) VALUES
  ('Double_Leg_Butt_Kick', 'Double Leg Butt Kick', 'double-leg-butt-kick', 'Legs & Glutes', 'Push', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['abductors', 'adductors', 'calves', 'glutes', 'hamstrings']::text[], ARRAY['Begin standing with your knees slightly bent.', 'Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.', 'As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.', 'Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.']::text[], ARRAY['/exercises/double-leg-butt-kick-1.webp', '/exercises/double-leg-butt-kick-2.webp']::text[], ARRAY[]::text[]),
  ('Dumbbell_Lunges', 'Dumbbell Lunges', 'dumbbell-lunges', 'Legs & Glutes', 'Squat', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings']::text[], ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], ARRAY['/exercises/dumbbell-lunges-1.webp', '/exercises/dumbbell-lunges-2.webp']::text[], ARRAY[]::text[]),
  ('Dumbbell_Lying_Pronation', 'Dumbbell Lying Pronation', 'dumbbell-lying-pronation', 'Arms', 'Pull', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.', 'Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/dumbbell-lying-pronation-1.webp', '/exercises/dumbbell-lying-pronation-2.webp']::text[], ARRAY[]::text[]),
  ('Dumbbell_Side_Bend', 'Dumbbell Side Bend', 'dumbbell-side-bend', 'Core', 'Core', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions and then change hands.']::text[], ARRAY['/exercises/dumbbell-side-bend-1.webp', '/exercises/dumbbell-side-bend-2.webp']::text[], ARRAY[]::text[]),
  ('Elevated_Cable_Rows', 'Elevated Cable Rows', 'elevated-cable-rows', 'Back', 'Pull', ARRAY['Machine']::text[], 'Intermediate', ARRAY['lats']::text[], ARRAY['middle back', 'traps']::text[], ARRAY['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.', 'Place it on the seat of the cable row machine.', 'Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/elevated-cable-rows-1.webp', '/exercises/elevated-cable-rows-2.webp']::text[], ARRAY[]::text[]),
  ('Elliptical_Trainer', 'Elliptical Trainer', 'elliptical-trainer', 'Cardio', 'Cardio', ARRAY['Machine']::text[], 'Intermediate', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings']::text[], ARRAY['To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], ARRAY['/exercises/elliptical-trainer-1.webp', '/exercises/elliptical-trainer-2.webp']::text[], ARRAY[]::text[]),
  ('Face_Pull', 'Face Pull', 'face-pull', 'Shoulders', 'Pull', ARRAY['Machine']::text[], 'Intermediate', ARRAY['shoulders']::text[], ARRAY['middle back']::text[], ARRAY['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], ARRAY['/exercises/face-pull-1.webp', '/exercises/face-pull-2.webp']::text[], ARRAY[]::text[]),
  ('Flat_Bench_Cable_Flyes', 'Flat Bench Cable Flyes', 'flat-bench-cable-flyes', 'Chest', 'Push', ARRAY['Machine']::text[], 'Intermediate', ARRAY['chest']::text[], ARRAY[]::text[], ARRAY['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.', 'Lay flat on the bench and keep your feet on the ground.', 'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.', 'Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.', 'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.', 'Slowly come back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/flat-bench-cable-flyes-1.webp', '/exercises/flat-bench-cable-flyes-2.webp']::text[], ARRAY[]::text[]),
  ('Glute_Ham_Raise', 'Glute Ham Raise', 'glute-ham-raise', 'Legs & Glutes', 'Pull', ARRAY['Machine']::text[], 'Intermediate', ARRAY['hamstrings']::text[], ARRAY['calves', 'glutes']::text[], ARRAY['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.', 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.', 'Return to the starting position, keeping your descent under control.']::text[], ARRAY['/exercises/glute-ham-raise-1.webp', '/exercises/glute-ham-raise-2.webp']::text[], ARRAY[]::text[]),
  ('Goblet_Squat', 'Goblet Squat', 'goblet-squat', 'Legs & Glutes', 'Squat', ARRAY['Kettlebell']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings', 'shoulders']::text[], ARRAY['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.', 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.', 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[], ARRAY['/exercises/goblet-squat-1.webp', '/exercises/goblet-squat-2.webp']::text[], ARRAY[]::text[]),
  ('Handstand_Push-Ups', 'Handstand Push-Ups', 'handstand-push-ups', 'Shoulders', 'Push', ARRAY['Bodyweight']::text[], 'Expert', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['With your back to the wall bend at the waist and place both hands on the floor at shoulder width.', 'Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.', 'Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.', 'Push yourself back up slowly as you exhale until your elbows are nearly locked.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/handstand-push-ups-1.webp', '/exercises/handstand-push-ups-2.webp']::text[], ARRAY[]::text[]),
  ('Hanging_Leg_Raise', 'Hanging Leg Raise', 'hanging-leg-raise', 'Core', 'Core', ARRAY['Bodyweight']::text[], 'Expert', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.', 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.', 'Go back slowly to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/hanging-leg-raise-1.webp', '/exercises/hanging-leg-raise-2.webp']::text[], ARRAY[]::text[]),
  ('High_Cable_Curls', 'High Cable Curls', 'high-cable-curls', 'Arms', 'Pull', ARRAY['Machine']::text[], 'Intermediate', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.', 'Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.', 'Slowly bring back the arms to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/high-cable-curls-1.webp', '/exercises/high-cable-curls-2.webp']::text[], ARRAY[]::text[]),
  ('Hyperextensions_With_No_Hyperextension_Bench', 'Hyperextensions With No Hyperextension Bench', 'hyperextensions-with-no-hyperextension-bench', 'Back', 'Pull', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['lower back']::text[], ARRAY['glutes', 'hamstrings']::text[], ARRAY['With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.', 'Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/hyperextensions-with-no-hyperextension-bench-1.webp', '/exercises/hyperextensions-with-no-hyperextension-bench-2.webp']::text[], ARRAY[]::text[]),
  ('Incline_Push-Up_Medium', 'Incline Push-Up Medium', 'incline-push-up-medium', 'Chest', 'Push', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['abdominals', 'shoulders', 'triceps']::text[], ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[], ARRAY['/exercises/incline-push-up-medium-1.webp', '/exercises/incline-push-up-medium-2.webp']::text[], ARRAY[]::text[]),
  ('Kettlebell_Pirate_Ships', 'Kettlebell Pirate Ships', 'kettlebell-pirate-ships', 'Shoulders', 'Push', ARRAY['Kettlebell']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY['abdominals']::text[], ARRAY['With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.', 'Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.', 'Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.', 'Repeat for the desired amount of repetitions.']::text[], ARRAY['/exercises/kettlebell-pirate-ships-1.webp', '/exercises/kettlebell-pirate-ships-2.webp']::text[], ARRAY[]::text[]),
  ('Kettlebell_Pistol_Squat', 'Kettlebell Pistol Squat', 'kettlebell-pistol-squat', 'Legs & Glutes', 'Squat', ARRAY['Kettlebell']::text[], 'Expert', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings', 'shoulders']::text[], ARRAY['Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.', 'Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.', 'Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.', 'Lower yourself again and repeat.']::text[], ARRAY['/exercises/kettlebell-pistol-squat-1.webp', '/exercises/kettlebell-pistol-squat-2.webp']::text[], ARRAY[]::text[]),
  ('Leg-Over_Floor_Press', 'Leg-Over Floor Press', 'leg-over-floor-press', 'Chest', 'Push', ARRAY['Kettlebell']::text[], 'Intermediate', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.', 'Press the kettlebll into a locked out position.', 'Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.']::text[], ARRAY['/exercises/leg-over-floor-press-1.webp', '/exercises/leg-over-floor-press-2.webp']::text[], ARRAY[]::text[]),
  ('Lying_Crossover', 'Lying Crossover', 'lying-crossover', 'Mobility & Stretching', 'Push', ARRAY['Bodyweight']::text[], 'Expert', ARRAY['abductors']::text[], ARRAY[]::text[], ARRAY['Lie on your back with your legs extended.', 'Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.', 'Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.', 'After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side.']::text[], ARRAY['/exercises/lying-crossover-1.webp', '/exercises/lying-crossover-2.webp']::text[], ARRAY[]::text[]),
  ('Middle_Back_Shrug', 'Middle Back Shrug', 'middle-back-shrug', 'Back', 'Pull', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['middle back']::text[], ARRAY[]::text[], ARRAY['Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.', 'As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.', 'As you inhale go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/middle-back-shrug-1.webp', '/exercises/middle-back-shrug-2.webp']::text[], ARRAY[]::text[]),
  ('One_Arm_Chin-Up', 'One Arm Chin-Up', 'one-arm-chin-up', 'Back', 'Pull', ARRAY['Bar']::text[], 'Expert', ARRAY['middle back']::text[], ARRAY['biceps', 'forearms', 'lats']::text[], ARRAY['For this exercise, start out by placing a towel around a chin up bar.', 'Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.', 'Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.', 'Switch arms and repeat the movement.']::text[], ARRAY['/exercises/one-arm-chin-up-1.webp', '/exercises/one-arm-chin-up-2.webp']::text[], ARRAY[]::text[]),
  ('Plyo_Kettlebell_Pushups', 'Plyo Kettlebell Pushups', 'plyo-kettlebell-pushups', 'Chest', 'Push', ARRAY['Kettlebell']::text[], 'Expert', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.', 'Begin by lowering yourself as low as you can, keeping your back straight.', 'Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.']::text[], ARRAY['/exercises/plyo-kettlebell-pushups-1.webp', '/exercises/plyo-kettlebell-pushups-2.webp']::text[], ARRAY[]::text[]),
  ('Rocky_Pull-Ups_Pulldowns', 'Rocky Pull-Ups/Pulldowns', 'rocky-pull-ups-pulldowns', 'Back', 'Pull', ARRAY['Bar']::text[], 'Intermediate', ARRAY['lats']::text[], ARRAY['biceps', 'middle back', 'shoulders']::text[], ARRAY['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.', 'Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program.']::text[], ARRAY['/exercises/rocky-pull-ups-pulldowns-1.webp', '/exercises/rocky-pull-ups-pulldowns-2.webp']::text[], ARRAY[]::text[]),
  ('Upright_Row_-_With_Bands', 'Upright Row - With Bands', 'upright-row-with-bands', 'Back', 'Pull', ARRAY['Band']::text[], 'Beginner', ARRAY['traps']::text[], ARRAY['shoulders']::text[], ARRAY['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/upright-row-with-bands-1.webp', '/exercises/upright-row-with-bands-2.webp']::text[], ARRAY[]::text[]),
  ('Air_Bike', 'Air Bike', 'air-bike', 'Core', 'Core', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.', 'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.', 'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.', 'Go back to the initial position as you breathe in.', 'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[], ARRAY['/exercises/air-bike-1.webp', '/exercises/air-bike-2.webp']::text[], ARRAY[]::text[]),
  ('Front_Leg_Raises', 'Front Leg Raises', 'front-leg-raises', 'Mobility & Stretching', 'Pull', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['hamstrings']::text[], ARRAY[]::text[], ARRAY['Stand next to a chair or other support, holding on with one hand.', 'Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs.']::text[], ARRAY['/exercises/front-leg-raises-1.webp', '/exercises/front-leg-raises-2.webp']::text[], ARRAY[]::text[]),
  ('Double_Kettlebell_Windmill', 'Double Kettlebell Windmill', 'double-kettlebell-windmill', 'Core', 'Core', ARRAY['Kettlebell']::text[], 'Intermediate', ARRAY['abdominals']::text[], ARRAY['glutes', 'hamstrings', 'shoulders', 'triceps']::text[], ARRAY['Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.', 'Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.', 'Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position.']::text[], ARRAY['/exercises/double-kettlebell-windmill-1.webp', '/exercises/double-kettlebell-windmill-2.webp']::text[], ARRAY[]::text[]),
  ('Groiners', 'Groiners', 'groiners', 'Mobility & Stretching', 'Pull', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['adductors']::text[], ARRAY[]::text[], ARRAY['Begin in a pushup position on the floor. This will be your starting position.', 'Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.', 'Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.']::text[], ARRAY['/exercises/groiners-1.webp', '/exercises/groiners-2.webp']::text[], ARRAY[]::text[]),
  ('Alternate_Incline_Dumbbell_Curl', 'Alternate Incline Dumbbell Curl', 'alternate-incline-dumbbell-curl', 'Arms', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[], ARRAY['/exercises/alternate-incline-dumbbell-curl-1.webp', '/exercises/alternate-incline-dumbbell-curl-2.webp']::text[], ARRAY[]::text[]),
  ('Bent_Over_Low-Pulley_Side_Lateral', 'Bent Over Low-Pulley Side Lateral', 'bent-over-low-pulley-side-lateral', 'Shoulders', 'Pull', ARRAY['Machine']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY['lower back', 'middle back', 'traps']::text[], ARRAY['Select a weight and hold the handle of the low pulley with your right hand.', 'Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.', 'Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.', 'Slowly lower the weight back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and repeat the movement with the other arm.']::text[], ARRAY['/exercises/bent-over-low-pulley-side-lateral-1.webp', '/exercises/bent-over-low-pulley-side-lateral-2.webp']::text[], ARRAY[]::text[])
